function paintRoute(){const old=stage.querySelector('.cw-route-overlay'),label=stage.querySelector('.cw-route-label');old?.remove();label?.remove();const route=window.CommonweaveActionableQuad?.activeRoute?.();if(!route)return;stage.style.position='relative';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','cw-route-overlay');svg.setAttribute('viewBox','0 0 1000 1600');svg.innerHTML='<path d="M500 1450 C230 1250 790 1050 490 850 S240 430 515 160"/>';stage.append(svg);const tag=document.createElement('button');tag.className='cw-route-label';tag.textContent=route.label+' · clear';tag.onclick=()=>{window.CommonweaveActionableQuad.clearRoute();paintRoute()};stage.append(tag)}
LW.bus.addEventListener('scene:visit',paintRoute);window.CommonweaveActionableQuad?.bus?.addEventListener('route:changed',paintRoute);
