panel.addEventListener('click',async e=>{const W=window.CommonweaveWeavelingSteward;if(!W)return;let el=e.target.closest('[data-weaveling-skill]');if(el){W.answerSkill(el.dataset.weavelingSkill,Number(el.dataset.level));const out=panel.querySelector('#cw-wish-output');if(out)out.innerHTML=renderWeavelingSession(W.session());return}if(e.target.closest('[data-weaveling-to-skills]')){const out=panel.querySelector('#cw-wish-output');if(out)out.innerHTML='<p>Weaveling is asking your configured model which capabilities actually matter for this wish…</p>';const prepared=await W.prepareSkills();if(out)out.innerHTML=renderWeavelingSession(prepared);return}if(e.target.closest('[data-weaveling-build]')){const out=panel.querySelector('#cw-wish-output');if(out)out.innerHTML='<p>Weaveling is mapping knowledge, materials, tasks, and realm handoffs…</p>';const plan=await W.buildPlan();if(out)out.innerHTML=renderWeavelingSession(plan);return}el=e.target.closest('[data-weaveling-remove]');if(el){W.removeTask(el.dataset.weavelingRemove);panel.querySelector('#cw-wish-output').innerHTML=renderWeavelingSession(W.session());return}if(e.target.closest('[data-weaveling-add]')){W.addTask();panel.querySelector('#cw-wish-output').innerHTML=renderWeavelingSession(W.session());return}if(e.target.closest('[data-weaveling-approve]')){const approved=W.approve();notify(approved?'Weaveling is now watching this intention':'The plan could not be approved');panel.querySelector('#cw-wish-output').innerHTML=renderWeavelingSession(W.session());return}el=e.target.closest('[data-weaveling-transport]');if(el){
 const target=el.dataset.weavelingTransport||W.nextRealm?.()||'commonweave';
 el.disabled=true;el.setAttribute('aria-busy','true');
 try{
  const payload=W.transport(target);if(!payload?.target)throw new Error('The route packet could not be prepared.');
  window.CommonweaveActionableQuad?.addMessage?.('assistant',payload.target==='commonweave'?`Let’s work the next step here: ${payload.next?.title||'review the intention route'}.`:`I packed the approved context for ${serviceMap[payload.target]||payload.target}. I will be here when you return.`,{weaveling:true});
  notify(payload.target==='commonweave'?'Opening the next Commonweave step…':`Opening ${serviceMap[payload.target]||payload.target}…`);
  if(payload.target==='commonweave'){showIntentions();return}
  const opened=openService(payload.target);if(!opened)throw new Error(`Could not open ${serviceMap[payload.target]||payload.target}.`);
 }catch(error){notify(error.message||'Realm travel failed.');el.disabled=false;el.removeAttribute('aria-busy')}
 return}if(e.target.closest('[data-weaveling-reset]')){W.reset();const out=panel.querySelector('#cw-wish-output');if(out){out.hidden=false;out.innerHTML='<p>What is your next wish?</p>'}return}});
